/* Cyberpunk Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="cyberpunk-light"] {
  --background: hsl(300 0% 97.37%);
  --foreground: hsl(241.26 48.11% 7.87%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(241.26 48.11% 7.87%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(241.26 48.11% 7.87%);
  --primary: hsl(312.95 99.97% 49.75%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(240 99.88% 97.09%);
  --secondary-foreground: hsl(241.26 48.11% 7.87%);
  --muted: hsl(240 99.88% 97.09%);
  --muted-foreground: hsl(241.26 48.11% 7.87%);
  --accent: hsl(166.49 99.27% 56.2%);
  --accent-foreground: hsl(241.26 48.11% 7.87%);
  --destructive: hsl(13.38 97.43% 51.15%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(197.99 21.4% 89.31%);
  --input: hsl(197.99 21.4% 89.31%);
  --ring: hsl(312.95 99.97% 49.75%);
  --chart-1: hsl(312.95 99.97% 49.75%);
  --chart-2: hsl(272.59 98.63% 52.32%);
  --chart-3: hsl(186.13 99.7% 49.75%);
  --chart-4: hsl(166.49 99.27% 56.2%);
  --chart-5: hsl(53.33 100% 58.05%);
  --radius: 0.5rem;
  --sidebar: hsl(240 99.88% 97.09%);
  --sidebar-foreground: hsl(241.26 48.11% 7.87%);
  --sidebar-primary: hsl(312.95 99.97% 49.75%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(166.49 99.27% 56.2%);
  --sidebar-accent-foreground: hsl(241.26 48.11% 7.87%);
  --sidebar-border: hsl(197.99 21.4% 89.31%);
  --sidebar-ring: hsl(312.95 99.97% 49.75%);
  --font-sans: Outfit, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -2px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

